export const DRAFT_LABEL_DISCLAIMER = Object.freeze({
  nl: 'Conceptlabels van de broncatalogus; vertalingen en anatomische koppeling zijn nog niet vakinhoudelijk beoordeeld.',
  en: 'Draft source-catalog labels; translations and anatomical mappings have not yet been reviewed by specialists.',
});

/** Resolve a catalog entry without inventing a label for an unknown source key. */
export function displayLabel(entry, locale = 'en') {
  if (!entry || typeof entry.key !== 'string') return '';
  if (locale === 'nl' && Object.hasOwn(NL_LABELS, entry.key)) {
    return NL_LABELS[entry.key];
  }
  return typeof entry.label === 'string' ? entry.label : entry.key;
}
